def is_equal_to_sum_even(n):
    """Determines if a given integer is even and at least 8.
    Returns True if n is even and >=8, False otherwise.
    Raises TypeError for non-integer input."""
    if not isinstance(n, int):
        raise TypeError
    if n < 8 or n % 2 != 0:
        return False
    return True

